I'll analyze this NASTRAN quadrilateral plate bending element routine and translate it to C++17 with Eigen.

Let me start by understanding the key computational flow:
1. `KQDPLT` sets up geometry, forms R-matrix, loops over 4 sub-triangles calling `KTRBSC`
2. `KTRBSC` computes the basic bending triangle stiffness matrices

Let me write the initial implementation.

```cpp
#include <Eigen/Dense>
#include <iostream>
#include <cmath>
#include <vector>
#include <iomanip>

using namespace Eigen;
using namespace std;

// Global material/geometry state shared between routines
struct State {
    double G11, G12, G13, G22, G23, G33;
    double E, nu, t;
    double I; // moment of inertia
    double DEGRA = M_PI/180.0;
    double SINTH, COSTH;
    double XSUBB, XSUBC, YSUBC;
    double ELTEMP;
    bool NOGO = false;
};

static State S;

// Material routine: isotropic plate -> G matrix (bending)
// G = E/(1-nu^2) * [[1,nu,0],[nu,1,0],[0,0,(1-nu)/2]] * I  (times I handled in D)
void MAT_iso() {
    double E = S.E, nu = S.nu;
    double coef = E/(1.0 - nu*nu);
    S.G11 = coef * 1.0;
    S.G12 = coef * nu;
    S.G13 = 0.0;
    S.G22 = coef * 1.0;
    S.G23 = 0.0;
    S.G33 = coef * (1.0 - nu)/2.0;
}

// GMMATD: general matrix multiply with transpose options
// op(A) is m x k, op(B) is k x n -> C is m x n
// transa: 1 means use A^T, 0 means A
// transb: 1 means use B^T, 0 means B
MatrixXd gmmatd(const MatrixXd& A, int transa, const MatrixXd& B, int transb) {
    MatrixXd At = (transa==1) ? A.transpose() : A;
    MatrixXd Bt = (transb==1) ? B.transpose() : B;
    return At * Bt;
}

// INVERD: invert n x n matrix
MatrixXd inverd(const MatrixXd& H, bool& ising) {
    FullPivLU<MatrixXd> lu(H);
    if (!lu.isInvertible()) { ising = true; return MatrixXd::Zero(H.rows(), H.cols()); }
    ising = false;
    return lu.inverse();
}

// KTRBSC: basic bending triangle. Returns the 9 3x3 matrices (K^U) as a 9x9 matrix
// stored as 3x3 blocks. We'll return a 9x9 matrix where block (i,j) is K^U_ij.
// iopt=1: compute only the 9 3x3 matrices.
MatrixXd KTRBSC(double x1,double y1,double z1,
                double x2,double y2,double z2,
                double x3,double y3,double z3,
                double angle, double eye, double t2) {
    // E matrix 3x6 (rows: k,i,j vectors; cols: 3 nodes x 2? Actually E is 18 = 3x6)
    // E(11),E(14),E(17) = I vector; E(12),E(15),E(18)=J; E(1),E(4),E(7)=K
    // E is stored column-major as 3x6? Let's use 3x6 matrix E where
    // E(row, col): col 1..3 = node A,B,C for K? Actually E is 3x6.
    // From code: E(1),E(4),E(7) = K vector (col 1)
    //            E(11),E(14),E(17) = I vector (col 4)
    //            E(12),E(15),E(18) = J vector (col 5)
    // E(2),E(5),E(8) temp = RsubC-RsubA
    // E(10) used as start of second 3x3 block (E(10..18))
    // So E is 3x6, column-major: E(1..9) first 3 cols, E(10..18) next 3 cols.
    MatrixXd E = MatrixXd::Zero(3,6);
    auto eget = [&](int idx)->double& { // 1-based Fortran index into 18
        int c = (idx-1)/3; int r = (idx-1)%3; return E(r,c);
    };

    // I-vector = RsubB - RsubA
    eget(11) = x2 - x1;
    eget(14) = y2 - y1;
    eget(17) = z2 - z1;
    double XSUBB = sqrt(eget(11)*eget(11)+eget(14)*eget(14)+eget(17)*eget(17));
    if (XSUBB <= 1e-6) { S.NOGO = true; return MatrixXd::Zero(9,9); }
    eget(11)/=XSUBB; eget(14)/=XSUBB; eget(17)/=XSUBB;

    eget(2) = x3 - x1;
    eget(5) = y3 - y1;
    eget(8) = z3 - z1;
    double XSUBC = eget(11)*eget(2)+eget(14)*eget(5)+eget(17)*eget(8);

    eget(1) = eget(14)*eget(8) - eget(5)*eget(17);
    eget(4) = eget(2)*eget(17) - eget(11)*eget(8);
    eget(7) = eget(11)*eget(5) - eget(2)*eget(14);
    double YSUBC = sqrt(eget(1)*eget(1)+eget(4)*eget(4)+eget(7)*eget(7));
    if (YSUBC <= 1e-6) { S.NOGO = true; return MatrixXd::Zero(9,9); }
    eget(1)/=YSUBC; eget(4)/=YSUBC; eget(7)/=YSUBC;

    eget(12) = eget(4)*eget(17) - eget(14)*eget(7);
    eget(15) = eget(11)*eget(7) - eget(1)*eget(17);
    eget(18) = eget(1)*eget(14) - eget(11)*eget(4);
    double TEMP = sqrt(eget(12)*eget(12)+eget(15)*eget(15)+eget(18)*eget(18));
    eget(12)/=TEMP; eget(15)/=TEMP; eget(18)/=TEMP;
    eget(2)=0; eget(3)=0; eget(5)=0; eget(6)=0; eget(8)=0; eget(9)=0;
    eget(10)=0; eget(13)=0; eget(16)=0;

    double THETA = angle*S.DEGRA;
    S.SINTH = sin(THETA);
    S.COSTH = cos(THETA);
    if (fabs(S.SINTH) < 1e-6) S.SINTH = 0.0;

    // G matrix
    MAT_iso();
    Matrix3d G;
    G << S.G11,S.G12,S.G13,
         S.G12,S.G22,S.G23,
         S.G13,S.G23,S.G33;
    Matrix3d D = G * eye;

    double AREA = XSUBB*YSUBC/2.0;
    double XBAR = (XSUBB+XSUBC)/3.0;
    double YBAR = YSUBC/3.0;
    double XCSQ = XSUBC*XSUBC;
    double YCSQ = YSUBC*YSUBC;
    double XBSQ = XSUBB*XSUBB;
    double XCYC = XSUBC*YSUBC;
    double PX2 = (XBSQ+XSUBB*XSUBC+XCSQ)/6.0;
    double PY2 = YCSQ/6.0;
    double PXY2 = YSUBC*(XSUBB+2.0*XSUBC)/12.0;
    double XBAR3 = 3.0*XBAR;
    double YBAR3 = 3.0*YBAR;
    double YBAR2 = 2.0*YBAR;

    // A array 1-based, size 144. Use vector<double> A(145)
    vector<double> A(145, 0.0);
    auto d = [&](int i)->double { return D((i-1)%3, (i-1)/3); }; // D(1..9) column-major

    // K^X matrix A(1..36)
    A[1] = d(1);
    A[2] = d(3);
    A[3] = d(2);
    A[4] = d(1)*XBAR3;
    A[5] = d(2)*XBAR + YBAR2*d(3);
    A[6] = d(2)*YBAR3;
    A[7] = A[2];
    A[8] = d(9);
    A[9] = d(6);
    A[10] = d(3)*XBAR3;
    A[11] = d(6)*XBAR + YBAR2*d(9);
    A[12] = d(6)*YBAR3;
    A[13] = A[3];
    A[14] = A[9];
    A[15] = d(5);
    A[16] = d(2)*XBAR3;
    A[17] = d(5)*XBAR + YBAR2*d(6);
    A[18] = d(5)*YBAR3;
    A[19] = A[4];
    A[20] = A[10];
    A[21] = A[16];
    A[22] = d(1)*9.0*PX2;
    A[23] = d(2)*3.0*PX2 + 6.0*PXY2*d(3);
    A[24] = d(2)*9.0*PXY2;
    A[25] = A[5];
    A[26] = A[11];
    A[27] = A[17];
    A[28] = A[23];
    A[29] = d(5)*PX2 + 4.0*PXY2*d(6) + 4.0*PY2*d(9);
    A[30] = d(5)*3.0*PXY2 + 6.0*PY2*d(6);
    A[31] = A[6];
    A[32] = A[12];
    A[33] = A[18];
    A[34] = A[24];
    A[35] = A[30];
    A[36] = d(5)*9.0*PY2;
    TEMP = 4.0*AREA;
    for (int i=1;i<=36;i++) A[i]*=TEMP;

    // HBAR matrix A(37..72)
    for (int i=37;i<=72;i++) A[i]=0.0;
    A[37]=XBSQ;
    A[40]=XBSQ*XSUBB;
    A[44]=XSUBB;
    A[49]=-2.0*XSUBB;
    A[52]=-3.0*XBSQ;
    A[55]=XCSQ;
    A[56]=XCYC;
    A[57]=YCSQ;
    A[58]=XCSQ*XSUBC;
    A[59]=YCSQ*XSUBC;
    A[60]=YCSQ*YSUBC;
    A[62]=XSUBC;
    A[63]=YSUBC*2.0;
    A[65]=XCYC*2.0;
    A[66]=YCSQ*3.0;
    A[67]=-2.0*XSUBC;
    A[68]=-YSUBC;
    A[70]=-3.0*XCSQ;
    A[71]=-YCSQ;

    if (t2 != 0.0) {
        // G2X2 from MAT with MATID2 - for isotropic, G2X2 = G33*I? 
        // Actually G2X211,G2X212,G2X222 are transverse shear terms. For our test t2=0.
        // We'll implement generically but for isotropic plate these are 0.
        double G2X211=0, G2X212=0, G2X222=0;
        if (!(G2X211==0 && G2X212==0 && G2X222==0)) {
            Matrix2d G2X2;
            G2X2 << G2X211*t2, G2X212*t2, G2X212*t2, G2X222*t2;
            double DETERM = G2X2(0,0)*G2X2(1,1)-G2X2(1,0)*G2X2(0,1);
            Matrix2d J2X2;
            J2X2 << G2X2(1,1)/DETERM, -G2X2(0,1)/DETERM,
                    -G2X2(1,0)/DETERM, G2X2(0,0)/DETERM;
            TEMP = 2.0*d(2)+4.0*d(9);
            A[73] = -6.0*(J2X2(0,0)*d(1)+J2X2(0,1)*d(3));
            A[74] = -J2X2(0,0)*TEMP - 6.0*J2X2(0,1)*d(6);
            A[75] = -6.0*(J2X2(0,0)*d(6)+J2X2(0,1)*d(5));
            A[76] = -6.0*(J2X2(1,0)*d(1)+J2X2(1,1)*d(3));
            A[77] = -J2X2(1,0)*TEMP - 6.0*J2X2(1,1)*d(6);
            A[78] = -6.0*(J2X2(1,0)*d(6)+J2X2(1,1)*d(5));
            // GMMATD(G2X2(2x2), A(73)(2x3)) -> A(79) 2x3
            MatrixXd G2X2m(2,2); G2X2m<<G2X2(0,0),G2X2(0,1),G2X2(1,0),G2X2(1,1);
            MatrixXd H73(2,3); H73<<A[73],A[74],A[75],A[76],A[77],A[78];
            MatrixXd P79 = G2X2m*H73;
            for(int i=0;i<6;i++) A[79+i]=P79(i/3,i%3);
            // GMMATD(A(73)^T (3x2), A(79)(2x3)) -> A(85) 3x3
            MatrixXd H73T = H73.transpose();
            MatrixXd P85 = H73T*P79;
            for(int i=0;i<9;i++) A[85+i]=P85(i/3,i%3);
            for(int i=1;i<=3;i++){
                A[i+21]+=A[i+84]*AREA;
                A[i+27]+=A[i+87]*AREA;
                A[i+33]+=A[i+90]*AREA;
            }
            for(int i=1;i<=3;i++){
                A[i+39]+=XSUBB*A[i+72];
                A[i+57]+=XSUBC*A[i+72]+YSUBC*A[i+75];
            }
        }
    }

    // Invert H (A(37..72)) 6x6
    MatrixXd H(6,6);
    for(int i=0;i<6;i++) for(int j=0;j<6;j++) H(i,j)=A[37+i+6*j];
    bool ising;
    MatrixXd Hinv = inverd(H, ising);
    if (ising) { S.NOGO=true; return MatrixXd::Zero(9,9); }
    for(int i=0;i<6;i++) for(int j=0;j<6;j++) A[37+i+6*j]=Hinv(i,j);

    // K^Q = K^X * Hinv -> A(73..108) 6x6
    MatrixXd KX(6,6);
    for(int i=0;i<6;i++) for(int j=0;j<6;j++) KX(i,j)=A[1+i+6*j];
    MatrixXd KQ = KX*Hinv;
    for(int i=0;i<6;i++) for(int j=0;j<6;j++) A[73+i+6*j]=KQ(i,j);

    // K^II = Hinv^T * KQ -> A(109..144) 6x6
    MatrixXd KII = Hinv.transpose()*KQ;
    for(int i=0;i<6;i++) for(int j=0;j<6;j++) A[109+i+6*j]=KII(i,j);

    // S matrix 6x3
    MatrixXd Sm(6,3);
    Sm << 1,0,-XSUBB,
          0,1,0,
          0,0,1,
          1,YSUBC,-XSUBC,
          0,1,0,
          0,0,1;

    // K^IA = K^II * S -> A(46..63) 6x3
    MatrixXd KIA = KII*Sm;
    for(int i=0;i<6;i++) for(int j=0;j<3;j++) A[46+i+6*j]=KIA(i,j);

    // K^AA = S^T * KIA -> A(1..9) 3x3
    MatrixXd KAA = Sm.transpose()*KIA;
    for(int i=0;i<3;i++) for(int j=0;j<3;j++) A[1+i+3*j]=KAA(i,j);

    // multiply KIA by -1
    for(int i=46;i<=63;i++) A[i]=-A[i];

    // Arrange nine 3x3 matrices of K^U
    for(int i=28;i<=36;i++) A[i]=A[i+18];
    A[10]=A[46]; A[11]=A[49]; A[12]=A[52];
    A[13]=A[47]; A[14]=A[50]; A[15]=A[53];
    A[16]=A[48]; A[17]=A[51]; A[18]=A[54];
    A[19]=A[55]; A[20]=A[58]; A[21]=A[61];
    A[22]=A[56]; A[23]=A[59]; A[24]=A[62];
    A[25]=A[57]; A[26]=A[60]; A[27]=A[63];
    A[37]=A[109]; A[38]=A[110]; A[39]=A[111];
    A[40]=A[115]; A[41]=A[116]; A[42]=A[117];
    A[43]=A[121]; A[44]=A[122]; A[45]=A[123];
    A[46]=A[112]; A[47]=A[113]; A[48]=A[114];
    A[49]=A[118]; A[50]=A[119]; A[51]=A[120];
    A[52]=A[124]; A[53]=A[125]; A[54]=A[126];
    A[64]=A[127]; A[65]=A[128]; A[66]=A[129];
    A[67]=A[133]; A[68]=A[134]; A[69]=A[135];
    A[70]=A[139]; A[71]=A[140]; A[72]=A[141];
    A[73]=A[130]; A[74]=A[131]; A[75]=A[132];
    A[76]=A[136]; A[77]=A[137]; A[78]=A[138];
    A[79]=A[142]; A[80]=A[143]; A[81]=A[144];

    // Return 9x9 matrix of K^U blocks. Block (i,j) at A(9*(i-1)+3*(j-1)+1)
    // Actually the 9 3x3 matrices are stored at A(1..81) as 3x3 blocks in row-major block order.
    MatrixXd KU(9,9);
    for(int bi=0;bi<3;bi++) for(int bj=0;bj<3;bj++){
        int base = 9*(bi*3+bj); // 0-based offset into A(1..81)
        for(int r=0;r<3;r++) for(int c=0;c<3;c++)
            KU(bi*3+r, bj*3+c) = A[1+base+r+3*c];
    }
    return KU;
}

int main() {
    // Test case
    S.E = 200e9;
    S.nu = 0.3;
    S.t = 0.01;
    S.I = S.t*S.t*S.t/12.0;

    // Quad nodes
    double X[4]={0,1,1,0};
    double Y[4]={0,0,1,1};
    double Z[4]={0,0,0,0};

    // Pivot point: choose NPVT = node 1 (index 0)
    int NPIVOT = 1; // 1-based
    int JNOT;
    if (NPIVOT-2 <= 0) JNOT = NPIVOT+2; else JNOT = NPIVOT-2;

    // R matrix 2x4
    MatrixXd R = MatrixXd::Zero(2,4);

    // D1 = VQ3 - VQ1, D2 = VQ4 - VQ2, A1 = VQ2 - VQ1
    Vector3d VQ1(X[0],Y[0],Z[0]);
    Vector3d VQ2(X[1],Y[1],Z[1]);
    Vector3d VQ3(X[2],Y[2],Z[2]);
    Vector3d VQ4(X[3],Y[3],Z[3]);
    Vector3d D1 = VQ3 - VQ1;
    Vector3d D2 = VQ4 - VQ2;
    Vector3d A1 = VQ2 - VQ1;

    Vector3d KVECT = D1.cross(D2);
    double TEMP = KVECT.norm();
    if (TEMP==0){S.NOGO=true;}
    KVECT/=TEMP;

    TEMP = A1.dot(KVECT)/2.0;
    Vector3d IVECT = A1 - TEMP*KVECT;
    TEMP = IVECT.norm();
    IVECT/=TEMP;

    Vector3d JVECT = KVECT.cross(IVECT);
    TEMP = JVECT.norm();
    JVECT/=TEMP;

    R(0,2) = D1.dot(IVECT); // R(1,3)
    R(0,1) = A1.dot(IVECT); // R(1,2)
    R(1,2) = D1.dot(JVECT); // R(2,3)
    R(0,3) = D2.dot(IVECT) + R(0,1); // R(1,4)
    R(1,3) = D2.dot(JVECT); // R(2,4)

    // M matrix mapping triangles
    int M[12] = {2,4,1, 3,1,2, 4,2,3, 1,3,4};

    // KSUM 9x9 (36 elements in Fortran = 6x6? No, KSUM(36) but used as 9x9)
    // Actually KSUM is dimensioned 36 but indexed up to 9*M(NPOINT)-9+9 = 9*4=36. So it's 36 elements = 6x6? 
    // Wait: NPOINT = 9*M(NPOINT)-9, then KSUM(NPOINT+1..+9). Max M=4 -> 9*4-9=27, +9=36. So KSUM is 36 elements.
    // But it's used as 9 3x3 blocks? No - it's indexed by 9*M-9 which gives block start. So KSUM holds 4 blocks of 9 = 36. 
    // It's a 6x6? No. Let's treat KSUM as 36-vector, blocks of 9 (3x3) indexed by node number.
    vector<double> KSUM(37, 0.0);

    // Loop over 4 sub-triangles
    for (int J=1; J<=4; J++) {
        if (J==JNOT) continue;
        int KM = 3*J-3;
        int SUBSCA = M[KM+0];
        int SUBSCB = M[KM+1];
        int SUBSCC = M[KM+2];

        // V = R(:,SUBSCB)-R(:,SUBSCA), VV = R(:,SUBSCC)-R(:,SUBSCA)
        Vector2d V, VV;
        for(int i=0;i<2;i++){
            V(i) = R(i,SUBSCB-1)-R(i,SUBSCA-1);
            VV(i)= R(i,SUBSCC-1)-R(i,SUBSCA-1);
        }
        double XSUBB = V.norm();
        double U1 = V(0)/XSUBB;
        double U2 = V(1)/XSUBB;
        double XSUBC = U1*VV(0)+U2*VV(1);
        double YSUBC = U1*VV(1)-U2*VV(0);

        double SINANG = sin(0.0); // THETA=0 for our test (ECPT(6)=0)
        double COSANG = cos(0.0);
        double SINTH = SINANG*U1 - COSANG*U2;
        double COSTH = COSANG*U1 + SINANG*U2;
        if (fabs(SINTH)<1e-6) SINTH=0.0;
        S.SINTH = SINTH; S.COSTH = COSTH;

        // Get the 3 node coordinates for this triangle
        double tx[3],ty[3],tz[3];
        int nodes[3]={SUBSCA,SUBSCB,SUBSCC};
        for(int i=0;i<3;i++){
            tx[i]=X[nodes[i]-1]; ty[i]=Y[nodes[i]-1]; tz[i]=Z[nodes[i]-1];
        }

        // Call KTRBSC with angle=0, eye=I, t2=0
        MatrixXd KU = KTRBSC(tx[0],ty[0],tz[0], tx[1],ty[1],tz[1], tx[2],ty[2],tz[2],
                             0.0, S.I, 0.0);
        if (S.NOGO) { cout<<"NOGO"<<endl; return 1; }

        // T matrix 3x3
        Matrix3d T;
        T << 1,0,0,
             0,U1,U2,
             0,-U2,U1;

        // Find which point of subtriangle is the pivot
        int NBEGIN=0;
        for(int i=1;i<=3;i++){
            int NPOINT = KM+i;
            if (M[NPOINT-1]==NPIVOT){ NBEGIN=27*i-27; break; }
        }

        // For each i=1..3: extract 3x3 block from KU, transform, add to KSUM
        for(int i=1;i<=3;i++){
            // block at A(NBEGIN+9*i-8) - 3x3 block
            int blkidx = (NBEGIN/9) + (i-1); // block index 0..8
            Matrix3d Ablk;
            for(int r=0;r<3;r++) for(int c=0;c<3;c++)
                Ablk(r,c) = KU((blkidx/3)*3+r, (blkidx%3)*3+c);

            // TEMP9 = T^T * Ablk
            Matrix3d TEMP9 = T.transpose()*Ablk;
            // PROD9 = TEMP9 * T
            Matrix3d PROD9 = TEMP9*T;

            // NPOINT = 9*M(KM+i)-9
            int NPOINT = 9*M[KM+i-1]-9;
            for(int k=1;k<=9;k++){
                NPOINT++;
                KSUM[NPOINT] += PROD9((k-1)%3,(k-1)/3)/2.0;
            }
        }
    }

    // E matrix 3x6
    MatrixXd E = MatrixXd::Zero(3,6);
    E(0,0)=KVECT(0); E(1,0)=KVECT(1); E(2,0)=KVECT(2);
    E(0,3)=IVECT(0); E(1,3)=IVECT(1); E(2,3)=IVECT(2);
    E(0,4)=JVECT(0); E(1,4)=JVECT(1); E(2,4)=JVECT(2);

    // TITE = E (no transformation, CSID=0)
    MatrixXd TITE = E;

    // KOUT 12x12
    MatrixXd KOUT = MatrixXd::Zero(12,12);

    for(int J=1;J<=4;J++){
        // TJTE = E
        MatrixXd TJTE = E;

        // KSUM block for node J: 3x3 at KSUM(9*J-8)
        Matrix3d KsumJ;
